import pytest
from primes import is_prime


def test_small_primes():
    for n in [2, 3, 5, 7, 11, 13]:
        assert is_prime(n) is True


def test_small_composites():
    for n in [4, 6, 8, 10, 12, 14, 15]:
        assert is_prime(n) is False


def test_edge_cases():
